    floating-point numbers, compute its average.
    """

    result = 0.0

    for i in range(len(array) - 1):
        result += (array[i + 1] - array[i]) / 2.0

    return result

def product_of_consecutive_diffs(array: List[float]) -> float:
    """ Given a positive integer number x and an array of n-1 positive
    floating-point numbers, compute its product.
    """

    result = 1.0

    for i in range(len(array) - 1):
        result *= (array[i + 1] - array[i])

    return result


