def parse_nested_parens_simple(paren_string: str) -> List[int]:
    """ Input to this function is a string represented multiple groups for nested parentheses separated by spaces.
    For each of the group, output the deepest level of nesting of parentheses.
    E.g. (()()) has maximum two levels of nesting while ((())) has three.

    >>> parse_nested_parens_simple('(()()) ((())) () ((())()())')
    [2, 3, 1, 3]
    """

    def go(parens):
        levels = 0
        last_level = 0
        for c in parens:
            if c in ['(', ')']:
                last_level = max(last_level, levels)
                if c == ')':
                    levels -= 1
                elif c == '(':
                    levels += 1
            else:
                pass

        return last_level

    #

    nested_paren_group = paren_string.split()
    maximum_nested = []
    while nested_paren_group:
        level = 0
        for paren_group in nested_paren_group:
            for paren in paren_group:
                if paren == '(':
                    level += 1
                else:
                    level -= 1
                    if level == 0:
                        maximum_nested.append(level)
                        nested_paren_group.remove(paren_group)
                        break
    return maximum_nested


